CREATE TABLE IF NOT EXISTS enforcement_cases(id TEXT PRIMARY KEY,subject_user_id TEXT NOT NULL REFERENCES users(id),document_id TEXT NOT NULL REFERENCES documents(id),residency_number TEXT NOT NULL,amount INTEGER NOT NULL CHECK(amount>0),reason TEXT NOT NULL,ministry_id INTEGER NOT NULL CHECK(ministry_id IN (1,3,7)),created_by TEXT NOT NULL REFERENCES users(id),status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')),decided_by TEXT REFERENCES users(id),decided_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_enforcement_subject ON enforcement_cases(subject_user_id,status);
